; ============================================================================
; DISPLAY IOCS
; The LCD is two HD61202 controllers: left 50H..53H (cmd 50H, data 52H, status
; 55H? read 53H), right 54H..57H, and both at once 58H..5BH. Rows are pages
; 0..7, DSPLPTR is the hardware scroll offset (display start line command C0H
; + 8*n). LCDWK1: b0 16x16 kanji mode (2 text rows), b1 40-column mode, b2
; ..., b3 control-code font. Most routines call the P0-B0 hook entry first
; (CALL 00xxH: the user-vector check) and bracket the LCD access with
; LCDBUSY/LCDFREE (90B5H/90BDH) and CRSROFF (8924H). BSPCTR: display on/off (A
; b0) - command 3EH/3FH to both controllers.
; ============================================================================

;------------------------------------------------------------------------------
; 8123H - (00E5H) Display on / off (BSPCTR)
; A b0: command 3EH / 3FH to both controllers.
;------------------------------------------------------------------------------
BSPCTR_B6:
	call 00B8H                      ; 8123  cdb800
	and 01H                         ; 8126  e601
	or 3EH                          ; 8128  f63e
	call LCDRDY                     ; 812A  cd7f81
	out (P_LCD1C),a                 ; 812D  d350
	ret                             ; 812F  c9



;------------------------------------------------------------------------------
; 8130H - (0112H) Clear the screen (CLS)
; All 4 text rows and the status line; cursor home.
;------------------------------------------------------------------------------
CLS_B6:
	call 0079H                      ; 8130  cd7900
	push af                         ; 8133  f5
	push de                         ; 8134  d5
	push bc                         ; 8135  c5
	call CRSROFF                    ; 8136  cd2489
	call LCDBUSY                    ; 8139  cdb590
	ld c,50H                        ; 813C  0e50
	xor a                           ; 813E  af
	call LCDCOL                     ; 813F  cdfc81
	ld a,(DSPLPTR)                  ; 8142  3a5cf0
	ld d,a                          ; 8145  57
	ld e,04H                        ; 8146  1e04
L8148:
	call LCDPAGE                    ; 8148  cdf081
	xor a                           ; 814B  af
	ld b,40H                        ; 814C  0640
L814E:
	call LCDRDY                     ; 814E  cd7f81
	out (52H),a                     ; 8151  d352
	djnz L814E                      ; 8153  10f9
	inc d                           ; 8155  14
	ld a,d                          ; 8156  7a
	dec e                           ; 8157  1d
	jr nz,L8148                     ; 8158  20ee
	ld e,04H                        ; 815A  1e04
	ld c,50H                        ; 815C  0e50
L815E:
	call LCDPAGE                    ; 815E  cdf081
	xor a                           ; 8161  af
	call LCDCOL                     ; 8162  cdfc81
	ld b,3FH                        ; 8165  063f
L8167:
